func (h *BatchTransformHandler) detectPrimaryKey(execDB *gorm.DB, schemaName, tableName string) (string, error) {
	if strings.TrimSpace(schemaName) == "" {
		schemaName = "public"
	}
	var cols []string
	sql := `
        SELECT a.attname
        FROM pg_index i
        JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = ANY(i.indkey)
        WHERE i.indrelid = (?::text)::regclass AND i.indisprimary
        ORDER BY array_position(i.indkey, a.attnum)`
	qualified := schemaName + "." + tableName
	if err := execDB.Raw(sql, qualified).Scan(&cols).Error; err != nil {
		return "", err
	}
	if len(cols) != 1 {
		return "", nil
	}
	return cols[0], nil
}

